package com.aethercore.backend.fetch;

import org.hibernate.resource.jdbc.spi.StatementInspector;

import java.util.Collections;
import java.util.List;
import java.util.concurrent.CopyOnWriteArrayList;

/**
 * StatementInspector implementation to intercept and observe SQL statements
 * generated by Hibernate during JPA fetch experiments (M2-E4A).
 */
public class FetchStatementInspector implements StatementInspector {

    private static final List<String> STATEMENTS = new CopyOnWriteArrayList<>();

    public static void clear() {
        STATEMENTS.clear();
    }

    public static List<String> getStatements() {
        return Collections.unmodifiableList(STATEMENTS);
    }

    @Override
    public String inspect(String sql) {
        if (sql != null) {
            STATEMENTS.add(sql);
        }
        return sql;
    }
}
